import {sellerExplanation} from './seller-links.js?v=14';
import {cityName,destinationCover,hydrateDestinationPhotos,purchaseFor,matchedOffer,flightPanel} from './travel-view.js?v=14';
import {localityInput,resolvePlace,placeForAirport} from './localities.js?v=14';
import {enablePush,disablePush} from './push-notifications.js?v=14';
import {money,esc,status,latest,safeLink,validatePing,validateState,alertFor,milesComparison,freshState,demoState} from './core.js?v=14';
import {cloudConfig,configureCloud,signedIn,signIn,signOut,readCloud,writeCloud,cloudRevision,accountProfile,flightRequest} from './cloud-v2.js?v=14';
import {paintAccountProfile} from './profile.js';
const STORE='aeroping-v1', main=document.querySelector('#main'),modal=document.querySelector('#modal');
let state,filter='all',view='',revision=null,cloudBusy=false,cloudDirty=false,cloudConflict=false,cloudTimer,installPrompt,toastTimer;
try{const saved=localStorage.getItem(STORE);state=saved?validateState(JSON.parse(saved)):freshState();}catch{state=freshState();queueMicrotask(()=>toast('Não foi possível ler os dados. Você pode restaurar um backup nos ajustes.'));}
let accessRenderer=()=>'<div class="loading">Conectando ao AeroPing…</div>',settingsRenderer=null,searchRenderer=null,openSearch=null;
const titleMap={buscar:'Buscar passagens',radar:'Meu radar',viagens:'Nossas viagens',milhas:'Dinheiro ou milhas',alertas:'Central de pings',ajustes:'Ajustes'};
const statusName={hit:'Preço-alvo atingido',warm:'Na zona de calor',watch:'De olho no preço',paused:'Radar pausado',empty:'Aguardando cotação'};
const day=s=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.','');
const stamp=s=>new Date(s).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const uid=()=>crypto.randomUUID();
const pingById=id=>state.pings.find(p=>p.id===id);
const pageHeader=(eyebrow,title,description,button='')=>`<div class="page-heading"><div><div class="eyebrow"><span class="live-dot"></span>${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${button}</div>`;
function toast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('Armazenamento cheio ou indisponível. Exporte um backup.');}if(signedIn()&&revision!==null&&!cloudConflict){cloudDirty=true;clearTimeout(cloudTimer);cloudTimer=setTimeout(pushCloud,1200);}updateShell();}
function event(type,title,body,demo=false){state.events.unshift({id:uid(),type,title,body,at:new Date().toISOString(),demo});state.events=state.events.slice(0,500);}
function updateShell(){paintAccountProfile(accountProfile());document.querySelector('#nav-count').textContent=state.pings.filter(p=>!p.paused).length;document.querySelectorAll('#alert-dot,#top-dot').forEach(e=>e.hidden=!state.events.some(e=>!e.read));document.querySelector('#storage-label').textContent=cloudConflict?'Conflito: confira os ajustes':signedIn()?(cloudDirty?'Alterações para sincronizar':revision===null?'Nuvem aguardando conexão':'Sincronizado com o casal'):'Acesso privado do casal';}
function chart(p,large=false){const values=p.quotes.map(q=>q.price);if(!values.length)return `<svg class="${large?'large-chart':'sparkline'}" viewBox="0 0 300 60" role="img" aria-label="Sem histórico de preços"><path d="M0 45H300" stroke="#334252" stroke-dasharray="4 5"/><text x="150" y="30" fill="#7a8c9c" font-size="9" text-anchor="middle">Aguardando primeira consulta</text></svg>`;
 const w=large?600:300,h=large?190:65,pad=large?20:7;const min=Math.min(...values,p.target)*.94,max=Math.max(...values,p.target)*1.04,range=max-min||1;const y=n=>h-pad-(n-min)/range*(h-2*pad);const coords=values.map((v,i)=>[values.length===1?w/2:i/(values.length-1)*w,y(v)]);const points=coords.map(x=>x.join(',')).join(' '),last=coords.at(-1),color=status(p)==='hit'?'#e6ba5f':status(p)==='warm'?'#f4c475':'#8ca9bc';const gid='g'+p.id.replace(/[^\w]/g,'')+(large?'l':'s');
 return `<svg class="${large?'large-chart':'sparkline'}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Histórico de ${esc(p.city)}, cotação atual ${esc(money(values.at(-1)))}; linha tracejada: meta de ${esc(p.autoTarget&&!p.baselinePrice?'Automático':money(p.target))}"><defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${color}" stop-opacity=".16"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="M0 ${y(p.target)}H${w}" stroke="#bba16b" opacity=".35" stroke-dasharray="4 5"/><path d="M${coords[0].join(',')} L${points} L${last[0]},${h} L${coords[0][0]},${h}Z" fill="url(#${gid})"/><polyline points="${points}" fill="none" stroke="${color}" stroke-width="${large?2:1.6}" stroke-linejoin="round" vector-effect="non-scaling-stroke"/><circle cx="${last[0]}" cy="${last[1]}" r="${large?3.5:2.5}" fill="${color}"/></svg>`;
}
function card(p){const st=status(p),n=latest(p),buy=purchaseFor(p);return `<article class="ping-card ${p.paused?'is-paused':''}">${destinationCover(p,`<button class="destination-open" data-action="detail" data-id="${esc(p.id)}" aria-label="Ver viagem para ${esc(p.city)}"></button><span class="ping-status">${statusName[st]}</span><div class="ping-destination"><h2>${esc(p.city)}</h2><p>${esc(cityName(p.origin))} ↔ ${esc(cityName(p.destination))}</p></div>`)}<div class="ping-card-body"><p class="ping-dates">${day(p.depart)} – ${day(p.return)} <span>· 2 adultos</span></p><div class="ping-price-line"><div><span>Ida e volta / pessoa</span><strong>${n==null?'Aguardando preço':money(n)}</strong></div><div class="ping-target"><span>Sua meta</span><b>${p.autoTarget&&!p.baselinePrice?'A definir':money(p.target)}</b></div></div><div class="ping-rule"><span>${p.autoTarget&&!p.baselinePrice?'Primeira consulta pendente':`Aviso até ${money(p.target*(1+p.tolerance/100))} · margem ${p.tolerance}%`}</span>${p.lastScan?.status==='error'?'<span class="ping-retry">Consulta pendente</span>':''}</div><div class="ping-card-actions"><button class="btn ghost" data-action="detail" data-id="${esc(p.id)}">Ver viagem</button>${buy?`<a class="btn primary" href="${esc(buy.url)}" target="_blank" rel="noopener noreferrer">${esc(buy.label)} ↗</a>`:`<button class="btn primary" data-action="search" data-id="${esc(p.id)}">Buscar ofertas ↗</button>`}</div>${buy?`<p class="ping-price-note">${n<=p.target?'Dentro da meta.':n<=p.target*(1+p.tolerance/100)?'Dentro da margem de aviso.':'Preço atual acima da meta.'} Confirme a tarifa na fonte.</p>`:''}</div></article>`;}

function radarSvg(){return `<svg viewBox="0 0 360 360" fill="none" aria-hidden="true"><defs><linearGradient id="sweep"><stop stop-color="#e6ba5f" stop-opacity=".2"/><stop offset="1" stop-color="#e6ba5f" stop-opacity="0"/></linearGradient></defs><circle cx="180" cy="180" r="143" stroke="#bba16b" stroke-opacity=".14"/><circle cx="180" cy="180" r="108" stroke="#bba16b" stroke-opacity=".17"/><circle cx="180" cy="180" r="73" stroke="#bba16b" stroke-opacity=".2"/><circle cx="180" cy="180" r="38" stroke="#bba16b" stroke-opacity=".25"/><path d="M180 20V340M20 180H340M67 67L293 293M67 293L293 67" stroke="#bba16b" stroke-opacity=".08"/><g class="radar-sweep"><path d="M180 180L180 37A143 143 0 0 1 323 180Z" fill="url(#sweep)"/><path d="M180 180L323 180" stroke="#e6ba5f" stroke-opacity=".4"/></g><circle cx="249" cy="133" r="5" fill="#e6ba5f"/><circle cx="249" cy="133" r="12" stroke="#e6ba5f" stroke-opacity=".3"/><circle cx="117" cy="211" r="3" fill="#e6ba5f"/><circle cx="198" cy="262" r="3" fill="#e6ba5f" fill-opacity=".6"/><circle cx="180" cy="180" r="4" fill="#e6ba5f"/><text x="266" y="130" fill="#e6ba5f" font-size="9" font-family="monospace">LIS</text><text x="96" y="231" fill="#b6a276" font-size="9" font-family="monospace">GRU</text><text x="209" y="279" fill="#b6a276" font-size="9" font-family="monospace">HND</text></svg>`;}
function activity(e){return `<div class="activity"><div class="activity-icon ${e.type==='warm'?'warm':''}">${e.type==='hit'?'↘':e.type==='warm'?'◉':e.type==='vote'?'♡':'↗'}</div><div><strong>${esc(e.title)} ${e.demo?'<span class="demo-chip">EXEMPLO</span>':''}</strong><p>${esc(e.body)}</p></div><time datetime="${esc(e.at)}">${stamp(e.at)}</time></div>`;}
function empty(message='Crie o radar da próxima viagem.',description='Escolha um destino, defina quanto vocês querem pagar e comece a acompanhar as cotações.'){return `<div class="empty"><div class="empty-icon">◉</div><h2>${message}</h2><p>${description}</p><button class="btn primary" data-action="new">＋ Criar nosso primeiro ping</button></div>`;}
function renderRadar(){const pings=state.pings,active=pings.filter(p=>!p.paused),hits=active.filter(p=>status(p)==='hit'),selected=filter==='hit'?pings.filter(p=>status(p)==='hit'):filter==='warm'?pings.filter(p=>status(p)==='warm'):pings;return `<div class="radar-heading"><div><h1>Seus pings</h1><p>Destinos, preços e metas. Tudo em um só lugar.</p></div><button class="btn primary" data-action="new">＋ Criar ping</button></div><div class="radar-overview"><span><b>${active.length}</b> ativo${active.length!==1?'s':''}</span><span><b>${hits.length}</b> na meta</span><a href="#buscar">Buscar passagens ↗</a></div><div class="radar-filters" role="group" aria-label="Filtrar radares">${[['all','Todos'],['hit','Na meta'],['warm','Perto da meta']].map(([id,label])=>`<button data-action="filter" data-filter="${id}" class="${filter===id?'active':''}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><section class="ping-grid">${selected.length?selected.map(card).join(''):pings.length?'<div class="empty"><h2>Nenhum ping neste filtro.</h2><button class="btn ghost" data-action="filter" data-filter="all">Ver todos</button></div>':empty('Qual é o próximo destino?','Escolha a cidade, as datas e o valor que você quer pagar.')}</section><p class="radar-footnote">Consultas aproximadamente a cada 6 horas para até 8 pings ativos. A tarifa final é confirmada no fornecedor.</p>`;}

function renderTrips(){return pageHeader('NOSSA LISTA DE DESEJOS','Próxima parada: juntos.','Uma boa viagem começa quando os dois dizem “eu topo”.','<button class="btn primary" data-action="new">＋ Novo destino</button>')+`<div class="hint">${signedIn()?'As decisões são compartilhadas entre vocês.':'Neste modo, as decisões ficam neste navegador. Para usar nos dois celulares, conecte o Supabase nos ajustes.'} Cada botão registra a decisão indicada pelo nome.</div><section class="trip-plan">${state.pings.length?state.pings.map(p=>`<article class="panel"><div class="plan-header"><div><span class="badge">${esc(p.origin)} → ${esc(p.destination)} ${p.demo?'· EXEMPLO':''}</span><h3 style="margin-top:12px">${esc(p.city)} a dois</h3><p class="detail-route">${day(p.depart)} a ${day(p.return)} · ${latest(p)==null?'Sem cotação':money(latest(p)*2)+' para o casal'}</p></div><button class="btn ghost" data-action="detail" data-id="${esc(p.id)}">Ver radar ↗</button></div><div class="votes">${[['a',state.settings.nameA],['b',state.settings.nameB]].map(([who,name])=>`<button class="btn ${p.votes?.[who]==='yes'?'selected':''}" data-action="vote" data-id="${esc(p.id)}" data-who="${who}">${p.votes?.[who]==='yes'?'✓':'♡'} ${esc(name)}: ${p.votes?.[who]==='yes'?'eu topo!':'ainda pensando'}</button>`).join('')}</div>${p.votes?.a==='yes'&&p.votes?.b==='yes'?'<p class="green" style="font-size:11px;margin-top:16px">✧ Combinado! Os dois toparam. Hora de conferir a tarifa na companhia.</p>':''}</article>`).join(''):empty()}</section>`;}
function renderMiles(){return pageHeader('CADA PONTO CONTA','Dinheiro ou milhas?','Transforme as duas opções na mesma moeda e decida com clareza.')+`<div class="compare-layout"><section class="panel"><h2 style="margin-bottom:23px">Vamos fazer as contas</h2><form id="miles-form"><div class="form-grid"><div class="field full"><label for="cash">Passagem em dinheiro (R$)</label><input id="cash" name="cash" type="number" min="1" max="10000000" step=".01" value="3200" required><small>Por pessoa, mesmo trecho e mesmas condições.</small></div><div class="field"><label for="miles">Quantidade de milhas</label><input id="miles" name="miles" type="number" min="1" max="100000000" value="80000" required></div><div class="field"><label for="thousand">Valor do milheiro (R$)</label><input id="thousand" name="thousand" type="number" min="0" max="10000" step=".01" value="25" required></div><div class="field full"><label for="taxes">Taxas da emissão com milhas (R$)</label><input id="taxes" name="taxes" type="number" min="0" max="1000000" step=".01" value="350" required></div></div><div class="form-actions"><button class="btn primary" type="submit">Comparar opções ↗</button></div></form></section><section class="panel"><span class="badge">◇ UMA DECISÃO MAIS CLARA</span><h2 style="margin-top:20px;font-size:23px;line-height:1.5">Suas milhas também<br>têm valor.</h2><p class="muted" style="font-size:12px;line-height:1.9;margin-top:17px">Informe o custo de compra ou o valor que você atribui às suas milhas. Mesmo os pontos já acumulados têm um custo de oportunidade.</p><div id="miles-result" aria-live="polite"></div><p class="price-source">Os valores preenchidos são exemplos editáveis. O cálculo considera milhas × custo do milheiro + taxas. Compare bagagem, regras de alteração e o mesmo número de passageiros. Nenhum programa de fidelidade é consultado.</p></section></div>`;}
function renderAlerts(){return pageHeader('A HORA CERTA DE FAZER AS MALAS','Cada ping, uma possibilidade.','Os sinais dos seus radares e as decisões de vocês, em um só lugar.','<button class="btn ghost" data-action="read-alerts">Marcar como lidos</button>')+`<div class="hint">Alertas são calculados quando uma cotação é registrada. Os radares são consultados em segundo plano. Ative os pings nos ajustes de cada aparelho para receber notificações.</div><div class="panel event-list">${state.events.length?state.events.map(activity).join(''):'<div class="empty"><div class="empty-icon">♧</div><h2>O próximo sinal aparece aqui.</h2><p>Crie um radar e registre cotações para acompanhar as mudanças de preço.</p></div>'}</div>`;}
function render(){view=location.hash.slice(1)||'radar';if(!titleMap[view])view='radar';document.querySelector('#page-name').textContent=titleMap[view];document.querySelectorAll('[data-nav]').forEach(e=>{e.classList.toggle('active',e.dataset.nav===view);if(e.dataset.nav===view)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});main.innerHTML=!signedIn()?accessRenderer():revision===null?'<div class="loading">Conectando ao nosso espaço…</div>':view==='buscar'&&searchRenderer?searchRenderer():view==='ajustes'&&settingsRenderer?settingsRenderer():({radar:renderRadar,viagens:renderTrips,milhas:renderMiles,alertas:renderAlerts,ajustes:()=>''}[view])();updateShell();hydrateDestinationPhotos(main);}
function showDialog(title,description,body){modal.classList.remove('journey-dialog');document.querySelector('#modal-body').innerHTML=`<div class="modal-header"><div><h2>${title}</h2><p>${description}</p></div><button data-action="close" aria-label="Fechar">×</button></div>${body}<p class="modal-error" id="modal-error" role="alert"></p>`;if(!modal.open)modal.showModal();}
function showPingForm(id,seed=null){const p=id?pingById(id):seed;if(id&&!p)return;const origin=p?.origin||state.settings.origin||state.pings[0]?.origin||'GRU';const dep=new Date(Date.now()+35*86400000).toISOString().slice(0,10),ret=new Date(Date.now()+42*86400000).toISOString().slice(0,10);showDialog(id?'Editar ping':'Criar ping','Destino, datas e o valor que você quer pagar.',`<form id="ping-form" data-id="${esc(p?.id||'')}"><div class="form-grid simple-ping-fields"><div class="field full"><label for="ping-locality">Para onde?</label>${localityInput('ping-locality','locality',p?.destination||'','Ex.: Rio de Janeiro, Lisboa, Paris')}</div><div class="field"><label for="depart">Ida</label><input id="depart" name="depart" type="date" value="${esc(p?.depart||dep)}" min="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label for="return">Volta</label><input id="return" name="return" type="date" value="${esc(p?.return||ret)}" min="${esc(p?.depart||dep)}" required></div><div class="field"><label for="target">Valor máximo por pessoa (R$)</label><input id="target" name="target" type="number" min="1" max="10000000" step=".01" value="${p&&!p.autoTarget?p.target:''}" placeholder="Ex.: 800" required><small>Ida e volta, por pessoa.</small></div><div class="field"><label for="tolerance">Avisar até (%) acima da meta</label><input id="tolerance" name="tolerance" type="number" min="0" max="50" step="1" value="${p?.autoTarget?10:p?.tolerance??10}" required><small>Ex.: meta R$ 800 + 10% = aviso até R$ 880.</small></div></div><details class="quiet-options"><summary>Saindo de ${esc(placeForAirport(origin)?.city||origin)} · alterar</summary><div class="field"><label for="ping-origin-city">Cidade de saída</label>${localityInput('ping-origin-city','originCity',origin)}</div></details><details class="quiet-options"><summary>Mais opções</summary><div class="form-grid"><div class="field"><label for="stops">Conexões</label><select id="stops" name="stops">${[['any','Qualquer opção'],['direct','Somente diretos'],['one','Até 1 parada']].map(([v,t])=>`<option value="${v}" ${p?.stops===v?'selected':''}>${t}</option>`).join('')}</select></div><label class="check-label field full"><input type="checkbox" name="baggage" ${p?.baggage?'checked':''}> Preciso de bagagem despachada</label></div></details><p class="minimal-help">Aeroportos definidos automaticamente. Sua meta vale por pessoa, para ida e volta.</p><div class="form-actions">${id?`<button class="btn danger" type="button" data-action="delete" data-id="${esc(p.id)}">Excluir</button>`:''}<button class="btn primary" type="submit">${id?'Salvar':'Criar ping'} ↗</button></div></form>`);}

function detail(id){const p=pingById(id);if(!p)return;const buy=purchaseFor(p),offer=matchedOffer(p),n=latest(p),at=buy?.at||p.quotes.at(-1)?.at;showDialog('','',`${destinationCover(p,`<div class="journey-cover-content"><p>${esc(cityName(p.origin))} ↔ ${esc(p.city)}</p><h2>${esc(p.city)}</h2><span>Ida e volta · Econômica · 2 adultos</span></div>`,'journey-cover')}<div class="journey-content"><div class="journey-monitor"><span class="monitor-icon">◉</span><div><strong>${p.paused?'Ping pausado':'Monitoramento ativo'}</strong><p>${p.autoTarget&&!p.baselinePrice?'Aguardando primeira cotação':`Meta ${money(p.target)} por pessoa · aviso até ${money(p.target*(1+p.tolerance/100))}`}</p></div><button class="text-button" data-action="edit" data-id="${esc(p.id)}">Editar</button></div><section class="journey-purchase"><div class="purchase-heading"><div><span>${buy?'Oferta encontrada / pessoa':'Última cotação / pessoa'}</span><strong>${n==null?'Aguardando preço':money(n)}</strong>${buy?`<small>${money(buy.total)} para 2 adultos · ida e volta</small>`:''}</div><span class="price-position">${n==null?'Sem cotação':n<=p.target?'Dentro da meta':n<=p.target*(1+p.tolerance/100)?'Perto da meta':'Acima da meta'}</span></div>${buy?`<a class="btn primary purchase-button" href="${esc(buy.url)}" target="_blank" rel="noopener noreferrer">${esc(buy.label)} <span>↗</span></a><p class="booking-explanation">${esc(sellerExplanation(buy))} O preço consultado pode mudar até a reserva.</p>`:`<button class="btn primary purchase-button" data-action="search" data-id="${esc(p.id)}">Buscar passagem ↗</button><p class="booking-explanation">O botão de compra aparece quando há uma cotação com link para a oferta.</p>`}${at?`<p class="purchase-updated">Consultado em ${new Date(at).toLocaleString('pt-BR')}</p>`:''}</section>${flightPanel(offer?.flights[0],0,p)}${flightPanel(offer?.flights[1],1,p)}<section class="journey-baggage"><h3>Informações sobre bagagens</h3><p>▣ ${p.baggage?'Você pediu bagagem despachada. A franquia deve ser confirmada antes da compra.':'Bagagem de mão e despachada: confira a franquia na opção de reserva.'}</p><small>A consulta não confirma a inclusão de bagagem despachada. Taxas adicionais podem ser cobradas pelo fornecedor.</small></section>${p.lastScan?.status==='error'?`<div class="journey-scan-note">${esc(p.lastScan.message)}${buy?' A última oferta registrada continua disponível para conferência.':''}</div>`:''}<details class="journey-history"><summary>Histórico de preços <span>${p.quotes.length} consulta${p.quotes.length===1?'':'s'}</span></summary>${p.quotes.length>1?chart(p,true):'<p>O histórico aparece conforme novas cotações são registradas.</p>'}<div class="quote-list">${p.quotes.slice(-5).reverse().map(q=>`<div class="quote-row"><span>${stamp(q.at)} · ${esc(q.source)}</span><strong>${money(q.price)}</strong></div>`).join('')}</div></details><div class="journey-tools"><button class="btn ghost" data-action="scan" data-id="${esc(p.id)}" ${p.paused?'disabled':''}>↻ Atualizar preço</button><button class="btn ghost" data-action="search" data-id="${esc(p.id)}">Outras ofertas</button><button class="btn ghost" data-action="pause" data-id="${esc(p.id)}">${p.paused?'Retomar ping':'Pausar ping'}</button><button class="text-button" data-action="quote" data-id="${esc(p.id)}">Registrar cotação manual</button><button class="btn ghost" data-action="close">Fechar viagem</button></div></div>`);modal.classList.add('journey-dialog');hydrateDestinationPhotos(document.querySelector('#modal-body'));}

function quoteForm(id){const p=pingById(id);if(!p||p.demo)return;showDialog(`Uma nova cotação para ${esc(p.city)}`,'Registre o valor visto no site da companhia ou buscador.',`<form id="quote-form" data-id="${esc(p.id)}"><div class="form-grid"><div class="field full"><label for="quote-price">Valor final por pessoa · ida e volta (R$)</label><input id="quote-price" name="price" type="number" min="1" max="10000000" step=".01" required autofocus><small>Inclua as taxas e a bagagem que você deseja. Para o casal, dividimos o total por duas pessoas.</small></div><div class="field full"><label for="quote-source">Onde você encontrou?</label><input id="quote-source" name="source" placeholder="LATAM, Google Voos…" maxlength="200" required></div><div class="field full"><label for="quote-url">Link da oferta (opcional, HTTPS)</label><input id="quote-url" name="url" type="url" placeholder="https://…"></div><label class="check-label" style="grid-column:1/-1"><input name="checked" type="checkbox" required> Conferi as datas, os 2 adultos e as preferências do radar.</label></div><div class="form-actions"><button class="btn primary" type="submit">Registrar e avaliar meta ↗</button></div></form>`);}
function confirmDialog(title,description,onConfirm,label='Confirmar'){showDialog(esc(title),esc(description),`<div class="form-actions"><button class="btn ghost" data-action="close">Cancelar</button><button id="confirm-action" class="btn primary">${esc(label)}</button></div>`);document.querySelector('#confirm-action').onclick=()=>{modal.close();onConfirm();};}
function exportBackup(){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=u;a.download=`aeroping-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Backup exportado. Guarde-o em um lugar seguro.');}
async function pushCloud(){if(cloudBusy||revision===null||!cloudDirty||cloudConflict||!signedIn())return;cloudBusy=true;const snapshot=JSON.stringify(state);let success=false;try{revision=await writeCloud(JSON.parse(snapshot),revision);cloudDirty=JSON.stringify(state)!==snapshot;success=true;}catch(e){cloudConflict=!!e.conflict;toast(e.message);}finally{cloudBusy=false;updateShell();if(view==='ajustes'||!signedIn())render();if(success&&cloudDirty&&!cloudConflict)cloudTimer=setTimeout(pushCloud,500);}}
async function connectCloud(){if(cloudBusy||!signedIn())return;cloudBusy=true;try{const remote=await readCloud();const incoming=remote.payload?validateState(remote.payload):freshState();const apply=()=>{state=incoming;revision=remote.revision;cloudDirty=false;cloudConflict=false;clearTimeout(cloudTimer);localStorage.setItem(STORE,JSON.stringify(state));render();};if(cloudDirty||cloudConflict){confirmDialog('Carregar os planos do casal?','As alterações locais serão substituídas. Exporte um backup antes se quiser guardá-las.',apply,'Carregar versão do casal');}else apply();}catch(e){if(!signedIn()){render();return;}toast(e.message);main.innerHTML='<div class="empty"><h2>Vamos tentar conectar de novo?</h2><p>Não foi possível abrir o espaço do casal. Confira a conexão e tente novamente.</p><button class="btn primary" data-action="sync">Tentar novamente</button><button class="btn ghost" data-action="logout" style="margin-left:8px">Sair</button></div>';}finally{cloudBusy=false;}}
async function checkSharedUpdates(){if(!signedIn()||document.hidden||cloudBusy||modal.open||cloudDirty||cloudConflict)return;try{if(revision===null){await connectCloud();return;}const remote=await cloudRevision();if(remote!==revision){if(cloudDirty||cloudBusy||modal.open)return;await connectCloud();}}catch{updateShell();if(!signedIn())render();}}
setInterval(checkSharedUpdates,30000);window.addEventListener('online',()=>{if(cloudDirty)pushCloud();else checkSharedUpdates();});window.addEventListener('focus',checkSharedUpdates);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id,p=pingById(id);if(!signedIn()&&!['close','install'].includes(action)){toast('Entre para acessar os planos do casal.');return;}switch(action){
case 'close':modal.close();break;
case 'new':showPingForm();break;
case 'edit':showPingForm(id);break;
case 'detail':detail(id);break;
case 'quote':quoteForm(id);break;
case 'scan':if(p&&!p.paused){b.disabled=true;b.textContent='Consultando…';try{await flushCloud();await flightRequest({mode:'scan',pingId:id});toast('Preço atualizado.');}catch(e){toast(e.message);}finally{await connectCloud();if(modal.open)detail(id);}}break;
case 'filter':filter=b.dataset.filter;render();break;
case 'profile':modal.close();location.hash='ajustes';break;
case 'alerts':location.hash='alertas';break;
case 'pause':if(p){p.paused=!p.paused;save();render();detail(id);toast(p.paused?'Radar pausado.':'Radar retomado.');}break;
case 'delete':if(p)confirmDialog('Excluir este radar?',`O destino ${p.city} e o seu histórico serão removidos.`,()=>{state.pings=state.pings.filter(x=>x.id!==id);save();render();toast('Radar excluído.');},'Excluir radar');break;
case 'clear-demo':confirmDialog('Começar com os nossos planos?','Os radares e alertas de demonstração serão removidos. Seus registros próprios serão preservados.',()=>{state.pings=state.pings.filter(x=>!x.demo);state.events=state.events.filter(x=>!x.demo);save();render();toast('Pronto para os seus destinos.');},'Remover exemplos');break;
case 'search':if(p&&openSearch){modal.close();openSearch(p);break;}if(p){const query=`Voos ${p.origin} ${p.destination} ida ${p.depart} volta ${p.return} 2 adultos`;window.open(`https://www.google.com/travel/flights?q=${encodeURIComponent(query)}`,'_blank','noopener,noreferrer');}break;
case 'vote':if(p){const who=b.dataset.who;if(!['a','b'].includes(who))break;p.votes??={a:null,b:null};p.votes[who]=p.votes[who]==='yes'?null:'yes';const name=who==='a'?state.settings.nameA:state.settings.nameB;event('vote',`${name} ${p.votes[who]==='yes'?'topou':'está pensando em'} ${p.city}`,p.votes.a==='yes'&&p.votes.b==='yes'?'Os dois toparam! Confiram a tarifa antes de reservar.':'A decisão pode ser alterada a qualquer momento.',p.demo);save();render();}break;
case 'read-alerts':state.events.forEach(e=>e.read=true);save();render();toast('Pings marcados como lidos.');break;
case 'export':exportBackup();break;
case 'import':document.querySelector('#import-file').click();break;
case 'reset':confirmDialog('Apagar os planos deste espaço?','Isso remove todos os radares, históricos e decisões. Se estiver conectado, a remoção também será sincronizada com o casal. Exporte um backup antes.',()=>{state=freshState();save();render();toast('Espaço limpo.');},'Apagar planos');break;
case 'notifications':try{await enablePush();toast('Pings ativados neste aparelho, inclusive com o app fechado.');}catch(e){toast(e.message);}break;
case 'disable-notifications':try{await disablePush();toast('Notificações desativadas neste aparelho.');}catch(e){toast(e.message);}break;
case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;}else showDialog('Leve o AeroPing com você','Use o navegador para instalar na tela inicial.',`<div class="hint">iPhone / iPad: abra no Safari, toque em Compartilhar → Adicionar à Tela de Início.<br><br>Android / computador: abra o menu do Chrome ou Edge → Instalar aplicativo ou Adicionar à tela inicial.<br><br>A instalação depende do navegador. Para compartilhar os dados, configure a mesma conexão Supabase nos dois aparelhos.</div>`);break;
case 'sync':if(cloudConflict||revision===null)await connectCloud();else if(cloudDirty)await pushCloud();else await connectCloud();break;
case 'logout':confirmDialog('Sair deste aparelho?','A cópia local será limpa. Alterações ainda não sincronizadas serão perdidas; exporte um backup antes.',async()=>{clearTimeout(cloudTimer);try{await disablePush();}catch{}await signOut();revision=null;cloudDirty=false;cloudConflict=false;state=freshState();localStorage.setItem(STORE,JSON.stringify(state));render();toast('Sessão encerrada. Dados locais removidos.');},'Sair e limpar');break;
}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id)return;e.preventDefault();const data=new FormData(form),value=k=>String(data.get(k)||'').trim();const button=form.querySelector('[type=submit]');try{
if(form.id==='ping-form'){const old=pingById(form.dataset.id);if(!old&&state.pings.length>=100)throw Error('O espaço comporta até 100 radares.');const destination=resolvePlace(value('locality')),origin=resolvePlace(value('originCity'));if(!destination||!origin)throw Error('Escolha uma cidade das sugestões. Não é necessário informar aeroporto.');const originCode=old&&placeForAirport(old.origin)?.label===origin.label?old.origin:origin.code,destinationCode=old&&placeForAirport(old.destination)?.label===destination.label?old.destination:destination.code,autoTarget=false;const p={...(old||{}),id:old?.id||uid(),city:destination.city,country:new Intl.DisplayNames(['pt-BR'],{type:'region'}).of(destination.country),origin:originCode,destination:destinationCode,depart:value('depart'),return:value('return'),autoTarget,target:autoTarget?(old?.autoTarget?old.target:1):Number(value('target')),tolerance:Number(value('tolerance')),stops:value('stops'),baggage:data.has('baggage'),paused:old?.paused||false,photo:old?.photo||({LIS:'lisbon',CDG:'paris',HND:'tokyo',NRT:'tokyo'}[destinationCode]||'other'),quotes:old?.quotes||[],votes:old?.votes||{a:null,b:null},createdAt:old?.createdAt||new Date().toISOString()};if(autoTarget&&!old?.autoTarget&&old?.quotes.length){p.baselinePrice=old.quotes[0].price;p.target=Math.max(1,Math.round(p.baselinePrice*.9*100)/100);}validatePing(p);if(old&&!old.demo&&old.quotes.length&&(old.origin!==p.origin||old.destination!==p.destination||old.depart!==p.depart||old.return!==p.return||old.stops!==p.stops||old.baggage!==p.baggage))throw Error('Crie outro ping para mudar uma viagem que já tem histórico.');if(old)state.pings[state.pings.findIndex(x=>x.id===old.id)]=p;else state.pings.unshift(p);state.settings.origin=originCode;save();modal.close();render();toast(old?'Ping atualizado.':'Ping criado. Buscando a primeira cotação…');if(!old){try{await flushCloud();await flightRequest({mode:'scan',pingId:p.id});}catch{toast('Ping salvo. A consulta será refeita automaticamente.');}finally{await connectCloud();}}}

if(form.id==='quote-form'){const p=pingById(form.dataset.id);if(!p||p.demo)throw Error('Crie um radar próprio para registrar cotações.');const price=Number(value('price')),url=value('url');if(!Number.isFinite(price)||price<=0||price>1e7)throw Error('Informe um preço válido.');if(url&&!safeLink(url))throw Error('Use um link HTTPS válido.');const previous=latest(p);p.quotes.push({price,source:value('source'),url,at:new Date().toISOString()});p.quotes=p.quotes.slice(-1000);const alert=alertFor(p,previous);if(alert){event(alert.type,alert.title,alert.body);if(state.settings.notifications&&'Notification'in window&&Notification.permission==='granted'){try{new Notification(alert.title,{body:alert.body,icon:'./icon-v10-192.png'});}catch{}}}save();render();detail(p.id);toast(alert?alert.title:'Cotação registrada no histórico.');}
if(form.id==='profile-form'){state.settings.nameA=value('nameA')||'Eu';state.settings.nameB=value('nameB')||'Viajante 2';save();render();toast('Nosso cantinho atualizado.');}
if(form.id==='miles-form'){const cash=Number(value('cash')),miles=Number(value('miles')),r=milesComparison(cash,miles,Number(value('thousand')),Number(value('taxes')));document.querySelector('#miles-result').innerHTML=`<div class="result-box"><h3>${Math.abs(r.saving)<.01?'As opções empatam':r.saving>0?'As milhas levam vantagem.':'O dinheiro leva vantagem.'}</h3><p>${Math.abs(r.saving)<.01?'O custo calculado é igual nas duas opções.':`Diferença estimada de <strong>${money(Math.abs(r.saving))}</strong> por pessoa e <strong>${money(Math.abs(r.saving)*2)}</strong> para o casal.`}</p><div class="result-numbers"><span>Em dinheiro<br><strong>${money(cash)}</strong></span><span>Com milhas + taxas<br><strong>${money(r.cost)}</strong></span></div><p style="margin-top:14px;font-size:10px">${r.breakEven>0?'Milhas compensam abaixo de '+money(r.breakEven)+' por milheiro, mantidas as mesmas condições.':'As taxas já são iguais ou superiores à passagem em dinheiro.'}</p></div>`;}
if(form.id==='cloud-config-form'){if(cloudBusy)throw Error('Aguarde a sincronização terminar.');configureCloud(value('url'),value('key'));revision=null;cloudDirty=false;cloudConflict=false;clearTimeout(cloudTimer);render();toast('Conexão salva. Entre na sua conta abaixo.');}
if(form.id==='login-form'){button.disabled=true;await signIn(value('email'),value('password'));form.reset();render();await connectCloud();}
}catch(error){const target=modal.open?document.querySelector('#modal-error'):null;if(target)target.textContent=error.message;else toast(error.message);}finally{if(button?.isConnected)button.disabled=false;}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files?.[0];if(!file)return;try{if(file.size>5e6)throw Error('O backup deve ter até 5 MB.');const incoming=validateState(JSON.parse(await file.text()));confirmDialog('Restaurar este backup?',`${incoming.pings.length} radar(es) substituirão os registros atuais. Se estiver conectado, serão sincronizados com o casal.`,()=>{state=incoming;save();render();toast('Backup restaurado.');},'Restaurar');}catch(err){toast(err.message);}finally{e.target.value='';}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});
window.addEventListener('storage',e=>{if(e.key==='aeroping-session-v2'){try{if(JSON.parse(e.oldValue||'null')?.user?.id===JSON.parse(e.newValue||'null')?.user?.id)return;}catch{}revision=null;cloudDirty=false;cloudConflict=false;state=freshState();render();if(signedIn())connectCloud();return;}if(e.key!==STORE||!e.newValue||!signedIn()||cloudDirty)return;try{state=validateState(JSON.parse(e.newValue));render();}catch{toast('Outra aba atualizou os dados. Confira o backup antes de continuar.');}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('beforeunload',e=>{if(cloudDirty){e.preventDefault();e.returnValue='';}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
render();if(signedIn())connectCloud();

export const sharedUi={get state(){return state;},get status(){return {dirty:cloudDirty,conflict:cloudConflict,ready:revision!==null};},radarSvg,pageHeader,toast,refreshPresentation:updateShell,render,createPing(query){showPingForm(null,{...query,autoTarget:true,tolerance:10});},configure(hooks){if(hooks.access)accessRenderer=hooks.access;if(hooks.settings)settingsRenderer=hooks.settings;if(hooks.search)searchRenderer=hooks.search;if(hooks.openSearch)openSearch=hooks.openSearch;render();},async addSearchRadar(q,offer,at){if(state.pings.length>=100)throw Error('O espaço comporta até 100 radares.');const p=validatePing({...q,id:uid(),country:q.country||'',tolerance:q.tolerance??10,paused:false,photo:'other',votes:{a:null,b:null},createdAt:new Date().toISOString(),quotes:q.baggage?[]:[{price:offer.perPerson,source:'Google Voos · busca',url:offer.bookingUrl,at}],bestOffer:offer});state.pings.unshift(p);save();await flushCloud();},async loginReady(){state=freshState();revision=null;cloudDirty=false;cloudConflict=false;render();await connectCloud();}};

async function flushCloud(){for(let i=0;cloudBusy&&i<100;i++)await new Promise(r=>setTimeout(r,100));if(cloudConflict||revision===null)throw Error('Sincronize os planos nos ajustes antes de continuar.');clearTimeout(cloudTimer);if(cloudDirty)await pushCloud();if(cloudDirty)throw Error('Não foi possível salvar. Confira sua conexão.');}
